package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BooleanSupplier;

/** Synthetic GRAY8 fixtures only. The real unchanged full-frame detector is exercised. */
public class NativeProgressRegionDiagnosticsTest {
    private static byte[] image(int w,int h,int value){byte[] p=new byte[w*h];Arrays.fill(p,(byte)value);return p;}
    private static void fill(byte[] p,int w,int l,int t,int r,int b,int value){for(int y=t;y<b;y++)Arrays.fill(p,y*w+l,y*w+r,(byte)value);}
    private static FrameStructureEvidence.Line row(String t,int x,int y,int w,int h,double s){return new FrameStructureEvidence.Line(t,x,y,w,h,s);}
    private static NativeProgressRegionDiagnostics observe(byte[] p,int w,int h,List<FrameStructureEvidence.Line> rows,BooleanSupplier cancel){Object o=new Object();var b=new FrameStructureEvidence.Binding(o,o,o,o);return NativeProgressRegionDiagnostics.observe(b,b,p,rows,w,h,cancel);}
    private static NativeProgressRegionDiagnostics observe(byte[] p,int w,int h,FrameStructureEvidence.Line... rows){return observe(p,w,h,List.of(rows),()->false);}
    @Test public void independentPixelRegionContainsReadingClueButOnlyHolds(){byte[] p=image(200,300,200);fill(p,200,10,30,190,130,255);String s=observe(p,200,300,row("read to earn",30,50,80,15,.99),row("0/30",140,60,30,15,.99)).summary(true);assertTrue(s,s.contains("structureEvidence=QUALIFIED"));assertTrue(s.contains("regionTotal=1 emitted=1"));assertTrue(s.contains("readingLabelRows=1"));assertTrue(s.contains("bareFractionRows=1"));assertTrue(s.contains("READING_CLUE_PRESENT_HOLD"));assertTrue(s.contains("counterAuthority=false actionAuthority=false"));assertFalse(s.contains("read to earn"));assertFalse(s.contains("0/30"));assertFalse(s.contains("=KNOWN"));}
    @Test public void ocrDoesNotCreateOrResizePixelRegion(){byte[] p=image(200,300,200);fill(p,200,10,30,190,130,255);String a=observe(p,200,300,row("read to earn",20,50,50,10,.99)).summary(true),b=observe(p,200,300,row("private unrelated",100,250,80,10,.99)).summary(true);assertTrue(a.contains("box=10,30,190,130"));assertTrue(b.contains("box=10,30,190,130"));}
    @Test public void bboxBrightnessCountsDisconnectedBrightPixelsNotComponentFill(){byte[] p=image(200,300,200);fill(p,200,10,20,190,120,255);fill(p,200,50,50,70,70,200);fill(p,200,55,55,65,65,255);String s=observe(p,200,300,row("reading unrelated",20,30,20,10,.99)).summary(true);assertTrue(s,s.contains("bboxBrightRatio=0.9833 brightPixels=17700 bboxPixels=18000"));assertTrue(s.contains("edgeL=255.0000/200.0000/55.0000"));}
    @Test public void mergedWhiteBackgroundDoesNotClaimCardOrClosedBoundary(){byte[] p=image(200,300,255);String s=observe(p,200,300,row("read to earn",30,50,80,15,.99)).summary(true);assertTrue(s,s.contains("regionTotal=1"));assertTrue(s.contains("box=0,0,200,300 bboxFrameClipped=true"));assertTrue(s.contains("bboxBrightRatio=1.0000"));assertTrue(s.contains("edgeL=255.0000/NA/NA"));assertTrue(s.contains("boundaryTopology=UNPROVEN"));assertFalse(s.contains("closed=true"));}
    @Test public void edgeClippingHasMissingOuterSamplesNotInventedContrast(){byte[] p=image(200,300,200);fill(p,200,0,30,190,130,255);String s=observe(p,200,300,row("read",20,40,40,10,.99)).summary(true);assertTrue(s.contains("bboxFrameClipped=true"));assertTrue(s.contains("edgeL=255.0000/NA/NA@200,0,true"));assertTrue(s.contains("edgeT=255.0000/200.0000/55.0000"));}
    @Test public void lowConfidenceInsideBoundaryOutsideAreSeparate(){byte[] p=image(200,300,200);fill(p,200,10,30,190,130,255);String s=observe(p,200,300,row("a",30,50,20,10,.4),row("b",180,50,20,10,.4),row("c",0,5,5,10,.4),row("d",10,60,20,10,.4)).summary(true);assertTrue(s,s.contains("containedRows=2 crossBoundaryRows=1 boundaryTouchOrCrossRows=2 multiHitRows=0 outsideRows=1 lowInsideRows=1 lowBoundaryRows=2 lowOutsideRows=1"));assertTrue(s.contains("boundaryRowIndices=[1, 3]"));}
    @Test public void spanningRowCountsCrossBoundaryAndMultiHitAcrossRegions(){byte[] p=image(200,300,200);fill(p,200,10,30,190,70,255);fill(p,200,10,90,190,130,255);String s=observe(p,200,300,row("read to earn",30,60,70,40,.4)).summary(true);assertTrue(s,s.contains("regionTotal=2"));assertTrue(s.contains("containedRows=0 crossBoundaryRows=1 boundaryTouchOrCrossRows=1 multiHitRows=1"));assertTrue(s.contains("lowBoundaryRows=1"));assertFalse(s.contains("readingLabelRows=1"));}
    @Test public void nestedComponentBoxesExposeMultiContainmentNotOwnership(){byte[] p=image(200,300,200);fill(p,200,5,5,195,295,255);fill(p,200,10,100,190,180,200);fill(p,200,20,110,180,160,255);String s=observe(p,200,300,row("read to earn",30,120,80,10,.99)).summary(true);assertTrue(s,s.contains("regionTotal=2"));assertTrue(s.contains("containedRows=1 crossBoundaryRows=0 boundaryTouchOrCrossRows=0 multiHitRows=1"));assertTrue(s.contains("semanticState=HOLD"));}
    @Test public void allRegionsCountEvenAfterEightRegionOutputCap(){byte[] p=image(100,500,200);for(int i=0;i<12;i++)fill(p,100,5,10+i*30,95,25+i*30,255);String s=observe(p,100,500,row("read to earn",20,342,40,4,.4),row("boundary",0,344,10,4,.4)).summary(true);assertTrue(s,s.contains("regionTotal=12 emitted=8 truncated=true"));assertTrue(s.contains("containedRows=1 crossBoundaryRows=1"));assertTrue(s.contains("lowInsideRows=1 lowBoundaryRows=1"));assertFalse(s.contains("region=8 "));}
    @Test public void rowIndexListsAreBoundedButCountsAreComplete(){byte[] p=image(200,300,200);fill(p,200,10,30,190,130,255);List<FrameStructureEvidence.Line> rows=new ArrayList<>();for(int i=0;i<20;i++)rows.add(row("unrelated",20,40,40,5,.99));String s=observe(p,200,300,rows,()->false).summary(true);assertTrue(s.contains("contained=20"));assertTrue(s.contains("containedRowIndices=[0, 1, 2, 3, 4, 5, 6, 7] containedIndicesTruncated=true"));assertFalse(s.contains("private unrelated"));}
    @Test public void invalidWholeRowShapeSuppressesEveryRegion(){byte[] p=image(200,300,255);String s=observe(p,200,300,row("read to earn",-1,50,50,10,.99)).summary(true);assertTrue(s.contains("ROW_SHAPE_REJECTED"));assertTrue(s.contains("regions=SUPPRESSED"));assertFalse(s.contains("bboxBrightRatio"));}
    @Test public void mismatchedBindingSuppressesEveryRegion(){Object a=new Object(),b=new Object();String s=NativeProgressRegionDiagnostics.observe(new FrameStructureEvidence.Binding(a,a,a,a),new FrameStructureEvidence.Binding(b,b,b,b),image(200,300,255),List.of(row("read",10,10,20,10,.99)),200,300,()->false).summary(true);assertTrue(s.contains("rowQuality=BINDING"));assertFalse(s.contains("box="));}
    @Test public void wrongImageLengthDoesNotReachGeometry(){String s=observe(new byte[5],200,300,row("read",10,10,20,10,.99)).summary(true);assertTrue(s.contains("INVALID_IMAGE"));assertTrue(s.contains("regions=SUPPRESSED"));}
    @Test public void immediateCancellationSuppressesGeometry(){String s=observe(image(200,300,255),200,300,List.of(row("read",10,10,20,10,.99)),()->true).summary(true);assertTrue(s.contains("state=CANCELED"));assertTrue(s.contains("regions=SUPPRESSED"));}
    @Test public void midWorkCancellationSuppressesPartialResults(){AtomicInteger calls=new AtomicInteger();String s=observe(image(200,300,255),200,300,List.of(row("read",10,10,20,10,.99)),()->calls.incrementAndGet()>10).summary(true);assertTrue(s,s.contains("state=CANCELED"));assertTrue(s.contains("regions=SUPPRESSED"));assertFalse(s.contains("region=0"));}
    @Test public void finalUnqualifiedSuppressesBoxesIndicesAndFeatures(){byte[] p=image(200,300,200);fill(p,200,10,30,190,130,255);String s=observe(p,200,300,row("read to earn",30,50,80,15,.99)).summary(false);assertTrue(s.contains("structureEvidence=UNQUALIFIED"));assertTrue(s.contains("regions=SUPPRESSED"));for(String token:new String[]{"box=","bboxBrightRatio","RowIndices","edgeL=","regionTotal=","lowInsideRows="})assertFalse(token,s.contains(token));}
    @Test public void sourcePixelsAreNotModifiedOrRetained(){byte[] p=image(200,300,200);fill(p,200,10,30,190,130,255);byte[] before=p.clone();var result=observe(p,200,300,row("read",30,50,80,15,.99));assertArrayEquals(before,p);String s=result.summary(true);Arrays.fill(p,(byte)0);assertEquals(s,result.summary(true));}
    @Test public void noPixelCandidatesCannotBeCreatedByOcrClues(){String s=observe(image(200,300,200),200,300,row("read to earn 30/30",30,50,80,15,.99)).summary(true);assertTrue(s.contains("detector=NO_CARDS"));assertTrue(s.contains("regionTotal=0 emitted=0"));assertFalse(s.contains("=KNOWN"));}
    @Test public void sameFrameLayoutIncludesCurrentAliasAndUnattributedFractionMetadata(){byte[] p=image(200,300,200);fill(p,200,10,30,190,130,255);String s=observe(p,200,300,row("search to earn",30,50,80,15,.99),row("17/61",120,70,40,10,.99)).summary(true);assertTrue(s.contains("sameFrameLayoutProjection=true"));assertTrue(s.contains("row=0 role=EXACT_REWARD_SEARCH_TITLE"));assertTrue(s.contains("row=1 role=BARE_FRACTION"));assertTrue(s.contains("n=17 d=61 fractionRole=UNATTRIBUTED"));assertFalse(s.contains("search to earn"));assertFalse(s.contains("=KNOWN"));}
    @Test public void titleFractionConflictsAreExplicitWithoutBinding(){byte[] p=image(200,300,200);fill(p,200,10,30,190,130,255);String s=observe(p,200,300,row("read to earn",20,40,80,10,.99),row("search points",20,55,80,10,.99),row("1/30",110,40,30,10,.99),row("2/60",110,55,30,10,.99),row("-1/0",110,70,30,10,.99)).summary(true);assertTrue(s,s.contains("readingLabelRows=1 searchLabelRows=1"));assertTrue(s.contains("bareFractionRows=2 malformedFractionRows=1 titleFractionConflictCount=2"));assertTrue(s.contains("MULTIPLE_LABEL_ROWS, MULTIPLE_BARE_FRACTIONS"));assertTrue(s.contains("association=NONE"));}
    @Test public void boundaryAndMultiregionCluesAreConflictFlags(){byte[] p=image(200,300,200);fill(p,200,10,30,190,70,255);fill(p,200,10,90,190,130,255);String s=observe(p,200,300,row("read to earn",30,60,70,40,.99)).summary(true);assertTrue(s.contains("titleFractionConflictFlags=[BOUNDARY_CLUE, MULTI_REGION_CLUE]"));}
    @Test public void fixedWholeFrameNearwhiteBinsDoNotChangeThreshold(){byte[] p=image(200,300,200);Arrays.fill(p,0,100,(byte)244);Arrays.fill(p,100,300,(byte)251);Arrays.fill(p,300,350,(byte)252);Arrays.fill(p,350,400,(byte)255);String s=observe(p,200,300,row("unrelated",10,10,30,10,.99)).summary(true);assertTrue(s,s.contains("frameGray0to243=59600 frameGray244to251=300 frameGray252to255=100 detectorBrightThreshold=252_UNCHANGED"));assertTrue(s.contains("regionTotal=0"));String unqualified=observe(p,200,300,row("unrelated",10,10,30,10,.99)).summary(false);assertFalse(unqualified.contains("frameGray"));}
    @Test public void omittedRegionsStillContributeReadingRegionTotals(){byte[] p=image(100,500,200);for(int i=0;i<12;i++)fill(p,100,5,10+i*30,95,25+i*30,255);String s=observe(p,100,500,row("read to earn",20,342,40,4,.99)).summary(true);assertTrue(s.contains("regionTotal=12 emitted=8 truncated=true"));assertTrue(s.contains("readingClueRegionTotal=1 searchClueRegionTotal=0"));assertFalse(s.contains("region=11 "));}
    @Test public void tooManyDetectorComponentsAreHoldNotPartialRegionSuccess(){byte[] p=image(100,600,200);for(int i=0;i<17;i++)fill(p,100,5,10+i*30,95,25+i*30,255);String s=observe(p,100,600,row("read",20,20,30,4,.99)).summary(true);assertTrue(s,s.contains("state=DETECTOR_HOLD detector=TOO_MANY_COMPONENTS"));assertTrue(s.contains("regions=SUPPRESSED"));assertFalse(s.contains("sameFrameLayoutProjection"));}
    @Test public void invalidScoreAndRowLimitCannotExposePartialLayout(){byte[] p=image(200,300,255);assertTrue(observe(p,200,300,row("read",10,10,30,10,Double.NaN)).summary(true).contains("regions=SUPPRESSED"));List<FrameStructureEvidence.Line> rows=new ArrayList<>();for(int i=0;i<129;i++)rows.add(row("read",10,10,30,10,.99));String s=observe(p,200,300,rows,()->false).summary(true);assertTrue(s.contains("rowQuality=ROW_LIMIT"));assertFalse(s.contains("sameFrameLayoutProjection"));}
    @Test public void cancelAfterMostWorkDropsAllComputedFeatures(){byte[] p=image(200,300,200);fill(p,200,10,30,190,130,255);List<FrameStructureEvidence.Line> rows=List.of(row("read",20,50,40,10,.99));AtomicInteger total=new AtomicInteger();observe(p,200,300,rows,()->{total.incrementAndGet();return false;});AtomicInteger calls=new AtomicInteger();String s=observe(p,200,300,rows,()->calls.incrementAndGet()>=total.get()-1).summary(true);assertTrue(s,s.contains("state=CANCELED"));assertTrue(s.contains("regions=SUPPRESSED"));assertFalse(s.contains("bboxBrightRatio"));assertFalse(s.contains("sameFrameLayoutProjection"));}
    @Test public void nestedBoxPairsCountWithoutAnyOcrHits(){byte[] p=image(200,300,200);fill(p,200,5,5,195,295,255);fill(p,200,10,100,190,180,200);fill(p,200,20,110,180,160,255);String s=observe(p,200,300,row("outside",0,0,3,3,.99)).summary(true);assertTrue(s,s.contains("regionBoxOverlapPairs=1 regionBoxNestedPairs=1"));assertTrue(s.contains("multiHitRows=0"));}
    @Test public void supportPairsUseFixedThresholdAndSuppressClippedPixels(){byte[] p=image(200,300,240);fill(p,200,10,30,190,130,255);String low=observe(p,200,300,row("read",30,50,30,10,.99)).summary(true);assertTrue(low,low.contains("support=0.0000 supportPairs=0/200"));Arrays.fill(p,(byte)239);fill(p,200,10,30,190,130,255);String high=observe(p,200,300,row("read",30,50,30,10,.99)).summary(true);assertTrue(high,high.contains("support=1.0000 supportPairs=200/200"));assertTrue(high.contains("supportDefinition=PAIRED_ABS_DIFF_GE_16"));String clipped=observe(image(200,300,255),200,300,row("read",30,50,30,10,.99)).summary(true);assertTrue(clipped.contains("support=NA supportPairs=0/0"));}
    @Test public void exteriorAbutmentIsOutsideNotBoundaryAndLabelsAreCluesOnly(){byte[] p=image(200,300,200);fill(p,200,10,30,190,130,255);String s=observe(p,200,300,row("Read and earn",20,20,90,10,.99)).summary(true);assertTrue(s,s.contains("boundaryTouchOrCrossRows=0 multiHitRows=0 outsideRows=1"));assertTrue(s.contains("labelsClueOnly=true labelProvenance=MIXED_SOURCE_AND_HYPOTHESIS boundaryDefinition=OVERLAPPING_ROWS_ONLY"));}
    @Test public void omittedRegionMembershipAndConflictTotalsAreNotClipped(){byte[] p=image(100,500,200);for(int i=0;i<12;i++)fill(p,100,5,10+i*30,95,25+i*30,255);String s=observe(p,100,500,row("read to earn",10,342,25,4,.99),row("search points",40,342,25,4,.99),row("1/30",10,348,20,4,.99),row("2/60",35,348,20,4,.99),row("-1/0",60,348,20,4,.99)).summary(true);assertTrue(s,s.contains("regionTotal=12 emitted=8 truncated=true"));assertTrue(s.contains("allRegionMembershipTotalsSearchLabel=1 allRegionMembershipTotalsReadingLabel=1 allRegionMembershipTotalsBareFraction=2 allRegionMembershipTotalsMalformedFraction=1"));assertTrue(s.contains("conflictRegionTotal_MULTIPLE_LABEL_ROWS=1 conflictRegionTotal_MULTIPLE_BARE_FRACTIONS=1"));assertTrue(s.contains("membershipSemantics=MAY_DOUBLECOUNT_OVERLAP_NO_OWNERSHIP"));assertFalse(s.contains("region=11 "));}
}
